  CONSTRAINT `departures_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `departures_vessel_id_foreign` FOREIGN KEY (`vessel_id`) REFERENCES `vessels` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `extras`;
CREATE TABLE `extras` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` bigint unsigned NOT NULL,
  `name` json NOT NULL,
  `description` json DEFAULT NULL,
  `pricing_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `price_cents` int unsigned DEFAULT NULL,
  `vat_rate_id` bigint unsigned DEFAULT NULL,
  `max_qty` smallint unsigned DEFAULT NULL,
  `is_tenant_wide` tinyint(1) NOT NULL DEFAULT '0',
  `is_required` tinyint(1) NOT NULL DEFAULT '0',
  `counts_toward_capacity` tinyint(1) NOT NULL DEFAULT '0',
  `prices_all_pax` tinyint(1) NOT NULL DEFAULT '0',
  `image_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `sort_order` smallint unsigned NOT NULL DEFAULT '0',
  `search_index` text COLLATE utf8mb4_unicode_ci,
  `name_sort_el` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `name_sort_en` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `extras_uuid_unique` (`uuid`),
  KEY `extras_vat_rate_id_foreign` (`vat_rate_id`),
  KEY `extras_tenant_active_idx` (`tenant_id`,`is_active`,`sort_order`),
  KEY `extras_tenant_wide_idx` (`tenant_id`,`is_tenant_wide`,`is_active`),
  KEY `extras_tenant_name_sort_el_idx` (`tenant_id`,`name_sort_el`),
  KEY `extras_tenant_name_sort_en_idx` (`tenant_id`,`name_sort_en`),
  CONSTRAINT `extras_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `extras_vat_rate_id_foreign` FOREIGN KEY (`vat_rate_id`) REFERENCES `vat_rates` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `failed_jobs`;
CREATE TABLE `failed_jobs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uuid` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `connection` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `queue` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `payload` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `exception` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `failed_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `failed_jobs_uuid_unique` (`uuid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `gateway_webhook_events`;
CREATE TABLE `gateway_webhook_events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned DEFAULT NULL,
  `provider` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL,
  `event_id` varchar(190) COLLATE utf8mb4_unicode_ci NOT NULL,
  `event_type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `signature_valid` tinyint(1) NOT NULL DEFAULT '0',
  `payload` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'received',
  `payment_id` bigint unsigned DEFAULT NULL,
  `error_message` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `processed_at` timestamp NULL DEFAULT NULL,
  `received_at` timestamp NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `gw_events_provider_event_uq` (`provider`,`event_id`),
  KEY `gateway_webhook_events_tenant_id_foreign` (`tenant_id`),
  KEY `gateway_webhook_events_payment_id_foreign` (`payment_id`),
  KEY `gw_events_status_idx` (`status`,`received_at`),
  CONSTRAINT `gateway_webhook_events_payment_id_foreign` FOREIGN KEY (`payment_id`) REFERENCES `payments` (`id`) ON DELETE SET NULL,
  CONSTRAINT `gateway_webhook_events_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `ical_feeds`;
CREATE TABLE `ical_feeds` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `vessel_id` bigint unsigned NOT NULL,
  `token` char(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `include_departures` tinyint(1) NOT NULL DEFAULT '1',
  `include_blocks` tinyint(1) NOT NULL DEFAULT '1',
  `include_guest_names` tinyint(1) NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `last_accessed_at` timestamp NULL DEFAULT NULL,
  `access_count` int unsigned NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ical_feeds_tenant_vessel_uq` (`tenant_id`,`vessel_id`),
  UNIQUE KEY `ical_feeds_token_unique` (`token`),
  KEY `ical_feeds_vessel_id_foreign` (`vessel_id`),
  CONSTRAINT `ical_feeds_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ical_feeds_vessel_id_foreign` FOREIGN KEY (`vessel_id`) REFERENCES `vessels` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `ical_sources`;
CREATE TABLE `ical_sources` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `vessel_id` bigint unsigned NOT NULL,
  `name` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `url` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `url_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `sync_interval_minutes` smallint unsigned NOT NULL DEFAULT '15',
  `last_synced_at` timestamp NULL DEFAULT NULL,
  `last_success_at` timestamp NULL DEFAULT NULL,
  `last_error` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `consecutive_failures` tinyint unsigned NOT NULL DEFAULT '0',
  `etag` varchar(190) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `events_imported` int unsigned NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ical_sources_url_hash_uq` (`tenant_id`,`url_hash`),
  KEY `ical_sources_vessel_id_foreign` (`vessel_id`),
  KEY `ical_sources_tenant_vessel_idx` (`tenant_id`,`vessel_id`),
  KEY `ical_sources_sync_idx` (`is_active`,`last_synced_at`),
  CONSTRAINT `ical_sources_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ical_sources_vessel_id_foreign` FOREIGN KEY (`vessel_id`) REFERENCES `vessels` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `integration_credentials`;
CREATE TABLE `integration_credentials` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `provider` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL,
  `environment` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'live',
  `credentials` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `public_config` json NOT NULL,
  `external_account_id` varchar(190) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_default` tinyint(1) NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `verified_at` timestamp NULL DEFAULT NULL,
  `last_error` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `webhook_secret` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `integr_creds_tenant_prov_env_uq` (`tenant_id`,`provider`,`environment`),
  KEY `integr_creds_tenant_active_idx` (`tenant_id`,`is_active`,`is_default`),
  KEY `integr_creds_provider_account_idx` (`provider`,`external_account_id`),
  CONSTRAINT `integration_credentials_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `job_batches`;
CREATE TABLE `job_batches` (
  `id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `total_jobs` int NOT NULL,
  `pending_jobs` int NOT NULL,
  `failed_jobs` int NOT NULL,
  `failed_job_ids` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `options` mediumtext COLLATE utf8mb4_unicode_ci,
  `cancelled_at` int DEFAULT NULL,
  `created_at` int NOT NULL,
  `finished_at` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `jobs`;
CREATE TABLE `jobs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `queue` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payload` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `attempts` tinyint unsigned NOT NULL,
  `reserved_at` int unsigned DEFAULT NULL,
  `available_at` int unsigned NOT NULL,
  `created_at` int unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `jobs_queue_index` (`queue`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `migrations`;
CREATE TABLE `migrations` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `migration` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `batch` int NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `password_reset_tokens`;
CREATE TABLE `password_reset_tokens` (
  `email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `token` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `payments`;
CREATE TABLE `payments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` bigint unsigned NOT NULL,
  `booking_id` bigint unsigned NOT NULL,
  `gateway` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL,
  `kind` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount_cents` int unsigned NOT NULL,
  `currency` char(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'EUR',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `gateway_ref` varchar(190) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gateway_transaction_ref` varchar(190) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `refunds_payment_id` bigint unsigned DEFAULT NULL,
  `idempotency_key` char(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `checkout_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `raw_payload` text COLLATE utf8mb4_unicode_ci,
  `failure_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `failure_message_el` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `failure_message_en` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `paid_at` timestamp NULL DEFAULT NULL,
  `refunded_at` timestamp NULL DEFAULT NULL,
  `recorded_by_user_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `payments_tenant_idem_uq` (`tenant_id`,`idempotency_key`),
  UNIQUE KEY `payments_uuid_unique` (`uuid`),
  KEY `payments_booking_id_foreign` (`booking_id`),
  KEY `payments_refunds_payment_id_foreign` (`refunds_payment_id`),
  KEY `payments_recorded_by_user_id_foreign` (`recorded_by_user_id`),
  KEY `payments_gateway_ref_idx` (`gateway`,`gateway_ref`),
  KEY `payments_tenant_booking_idx` (`tenant_id`,`booking_id`,`status`),
  KEY `payments_tenant_status_created_idx` (`tenant_id`,`status`,`created_at`),
  CONSTRAINT `payments_booking_id_foreign` FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `payments_recorded_by_user_id_foreign` FOREIGN KEY (`recorded_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `payments_refunds_payment_id_foreign` FOREIGN KEY (`refunds_payment_id`) REFERENCES `payments` (`id`) ON DELETE SET NULL,
  CONSTRAINT `payments_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `ports`;
CREATE TABLE `ports` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` bigint unsigned NOT NULL,
  `name` json NOT NULL,
  `address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lat` decimal(10,7) DEFAULT NULL,
  `lng` decimal(10,7) DEFAULT NULL,
  `instructions` json DEFAULT NULL,
  `photo_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `maps_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `sort_order` smallint unsigned NOT NULL DEFAULT '0',
  `search_index` text COLLATE utf8mb4_unicode_ci,
  `name_sort_el` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `name_sort_en` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ports_uuid_unique` (`uuid`),
  KEY `ports_tenant_active_idx` (`tenant_id`,`is_active`,`sort_order`),
  KEY `ports_tenant_name_sort_el_idx` (`tenant_id`,`name_sort_el`),
  KEY `ports_tenant_name_sort_en_idx` (`tenant_id`,`name_sort_en`),
  CONSTRAINT `ports_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `product_extra`;
CREATE TABLE `product_extra` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `product_id` bigint unsigned NOT NULL,
  `extra_id` bigint unsigned NOT NULL,
  `price_cents_override` int unsigned DEFAULT NULL,
  `max_qty_override` smallint unsigned DEFAULT NULL,
  `is_required_override` tinyint(1) DEFAULT NULL,
  `sort_order` smallint unsigned NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `product_extra_uq` (`tenant_id`,`product_id`,`extra_id`),
  KEY `product_extra_product_id_foreign` (`product_id`),
  KEY `product_extra_extra_id_foreign` (`extra_id`),
  KEY `product_extra_tenant_product_idx` (`tenant_id`,`product_id`,`sort_order`),
  CONSTRAINT `product_extra_extra_id_foreign` FOREIGN KEY (`extra_id`) REFERENCES `extras` (`id`) ON DELETE CASCADE,
  CONSTRAINT `product_extra_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE,
  CONSTRAINT `product_extra_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `products`;
CREATE TABLE `products` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` bigint unsigned NOT NULL,
  `vessel_id` bigint unsigned DEFAULT NULL,
  `slug` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mode` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` json NOT NULL,
  `summary` json DEFAULT NULL,
  `description` json DEFAULT NULL,
  `duration_minutes` smallint unsigned NOT NULL,
  `default_start_time` time DEFAULT NULL,
  `flexible_start` tinyint(1) NOT NULL DEFAULT '0',
  `earliest_start_time` time DEFAULT NULL,
  `latest_start_time` time DEFAULT NULL,
  `check_in_offset_minutes` smallint unsigned NOT NULL DEFAULT '30',
  `meeting_point_id` bigint unsigned DEFAULT NULL,
  `includes` json DEFAULT NULL,
  `excludes` json DEFAULT NULL,
  `what_to_bring` json DEFAULT NULL,
  `itinerary_stops` json DEFAULT NULL,
  `route_map_image_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `images` json NOT NULL,
  `min_pax` smallint unsigned NOT NULL DEFAULT '0',
  `max_pax` smallint unsigned NOT NULL,
  `min_booking_pax` smallint unsigned NOT NULL DEFAULT '1',
  `cancellation_policy_id` bigint unsigned DEFAULT NULL,
  `guest_details_required` tinyint(1) NOT NULL DEFAULT '0',
  `guest_details_deadline_hours` smallint unsigned NOT NULL DEFAULT '48',
  `vat_rate_id` bigint unsigned DEFAULT NULL,
  `mydata_income_class` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `price_from_cents` int unsigned DEFAULT NULL,
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `sort_order` smallint unsigned NOT NULL DEFAULT '0',
  `meta_title` json DEFAULT NULL,
  `meta_description` json DEFAULT NULL,
  `og_image_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_featured` tinyint(1) NOT NULL DEFAULT '0',
  `search_index` text COLLATE utf8mb4_unicode_ci,
  `title_sort_el` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title_sort_en` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `products_tenant_slug_unique` (`tenant_id`,`slug`),
  UNIQUE KEY `products_uuid_unique` (`uuid`),
  KEY `products_vessel_id_foreign` (`vessel_id`),
  KEY `products_meeting_point_id_foreign` (`meeting_point_id`),
  KEY `products_cancellation_policy_id_foreign` (`cancellation_policy_id`),
  KEY `products_vat_rate_id_foreign` (`vat_rate_id`),
  KEY `products_tenant_status_sort_idx` (`tenant_id`,`status`,`sort_order`),
  KEY `products_tenant_vessel_idx` (`tenant_id`,`vessel_id`),
  KEY `products_tenant_cat_status_idx` (`tenant_id`,`category`,`status`),
  KEY `products_tenant_mode_idx` (`tenant_id`,`mode`),
  KEY `products_tenant_title_sort_el_idx` (`tenant_id`,`title_sort_el`),
  KEY `products_tenant_title_sort_en_idx` (`tenant_id`,`title_sort_en`),
  CONSTRAINT `products_cancellation_policy_id_foreign` FOREIGN KEY (`cancellation_policy_id`) REFERENCES `cancellation_policies` (`id`) ON DELETE SET NULL,
  CONSTRAINT `products_meeting_point_id_foreign` FOREIGN KEY (`meeting_point_id`) REFERENCES `ports` (`id`) ON DELETE SET NULL,
  CONSTRAINT `products_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `products_vat_rate_id_foreign` FOREIGN KEY (`vat_rate_id`) REFERENCES `vat_rates` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `products_vessel_id_foreign` FOREIGN KEY (`vessel_id`) REFERENCES `vessels` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `rate_plan_prices`;
CREATE TABLE `rate_plan_prices` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `rate_plan_id` bigint unsigned NOT NULL,
  `age_band_id` bigint unsigned NOT NULL,
  `price_cents` int unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `rate_plan_prices_plan_band_uq` (`tenant_id`,`rate_plan_id`,`age_band_id`),
  KEY `rate_plan_prices_rate_plan_id_foreign` (`rate_plan_id`),
  KEY `rate_plan_prices_age_band_id_foreign` (`age_band_id`),
  KEY `rate_plan_prices_tenant_plan_idx` (`tenant_id`,`rate_plan_id`),
  CONSTRAINT `rate_plan_prices_age_band_id_foreign` FOREIGN KEY (`age_band_id`) REFERENCES `age_bands` (`id`) ON DELETE CASCADE,
  CONSTRAINT `rate_plan_prices_rate_plan_id_foreign` FOREIGN KEY (`rate_plan_id`) REFERENCES `rate_plans` (`id`) ON DELETE CASCADE,
  CONSTRAINT `rate_plan_prices_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `rate_plans`;
CREATE TABLE `rate_plans` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `product_id` bigint unsigned NOT NULL,
  `season_id` bigint unsigned DEFAULT NULL,
  `name` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vessel_price_cents` int unsigned DEFAULT NULL,
  `extra_hour_price_cents` int unsigned DEFAULT NULL,
  `deposit_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `deposit_percent` tinyint unsigned DEFAULT NULL,
  `deposit_fixed_cents` int unsigned DEFAULT NULL,
  `min_lead_time_hours` smallint unsigned NOT NULL DEFAULT '0',
  `max_advance_days` smallint unsigned DEFAULT NULL,
  `min_pax_override` smallint unsigned DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `balance_due_days_before_departure` smallint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `rate_plans_tenant_prod_season_uq` (`tenant_id`,`product_id`,`season_id`),
  KEY `rate_plans_product_id_foreign` (`product_id`),
  KEY `rate_plans_season_id_foreign` (`season_id`),
